    parent = [[[None] * (vlen + 1) for _ in range(m + 1)] for _ in range(n + 1)]

    for i in range(n + 1):
        for j in range(m + 1):
            for k in range(vlen + 1):
                if i == 0 or j == 0:
                    continue

                dp[i][j][k] = max(dp[i][j][k], dp[i - 1][j][k])
                parent[i][j][k] = ('i', k)

                dp[i][j][k] = max(dp[i][j][k], dp[i][j - 1][k])
                parent[i][j][k] = ('j', k)

                if s1[i - 1] == s2[j - 1]:
                    nk = get_next_state(k, s1[i - 1])
                    if nk < vlen:
                        if dp[i - 1][j - 1][k] + 1 > dp[i][j][nk]:
                            dp[i][j][nk] = dp[i - 1][j - 1][k] + 1
                            parent[i][j][nk] = ('diag', k)

    max_len = 0
    best_k = 0
    for k in range(vlen + 1):
        if dp[n][m][k] > max_len:
            max_len = dp[n][m][k]
            best_k = k

    if max_len == 0:
        return 0

    result = []
    i, j, k = n, m, best_k
    while i > 0 and j > 0:
        choice = parent[i][j][k]
        if choice[0] == 'diag':
            result.append(s1[i - 1])
            i -= 1
            j -= 1
            k = choice[1]
        elif choice[0] == 'i':
            i -= 1
            k = choice[1]
        else:
            j -= 1
            k = choice[1]

    return ''.join(reversed(result))
