Looking at this problem, I need to find the minimum day when Ivan can afford to buy all the microtransactions. This is a binary search problem where for a given target day D, I check if the total cost of all purchases (taking advantage of sale days) is ≤ D (the total earnings).

The key insight is:
- For each microtransaction type, count how many sale opportunities exist on or before day D
- Buy as many as possible at sale price (1 burle) then pay full price (2 burles) for the rest
- Total cost must be ≤ D (earnings by day D)

```python
def solution(data):
    if not data:
        return "0\n"

    try:
        lines = data.strip().split('\n')
        tokens = []
        for line in lines:
            tokens.extend(line.split())

        n = int(tokens[0])
        m = int(tokens[1])
        k = [int(tokens[2 + i]) for i in range(n)]

        offers = []
        idx = 2 + n
        for j in range(m):
            d = int(tokens[idx])
            t = int(tokens[idx + 1])
            offers.append((d, t))
            idx += 2

        # Group offers by type, keep unique days and sort
        offers_by_type = set()
        for d, t in offers:
            offers_by_type.add((d, t))

        offers_by_type = {}
        for d, t in offers:
            if t not in offers_by_type:
                offers_by_type[t] = []
            offers_by_type[t].append(d)

        for t in range(1, n + 1):
            offers_by_type[t] = sorted(list(set(offers_by_type[t])))

        def get_cost(day):
            cost = 0
            for i in range(n):
                if k[i] == 0:
                    continue

                type_idx = i + 1
                sale_days = offers_by_type.get(type_idx, [])

                # Count sales on or before 'day'
                sale_count = 0
                for sd in sale_days:
                    if sd <= day:
                        sale_count += 1
                    else:
                        break

                if sale_count > 0:
                    sale_buy = min(k[i], sale_count)
                    normal_buy = k[i] - sale_buy
                    cost += sale_buy + 2 * normal_buy
                else:
                    cost += 2 * k[i]

            return cost

        # Binary search for minimum day
        # Upper bound: sum of all k[i] * 2 (buying everything at full price)
        right = sum(k) * 2 + 2
        left = 1
        ans = right

        while left <= right:
            mid = (left + right) // 2
            if get_cost(mid) <= mid:
                ans = mid
                right = mid - 1
            else:
                left = mid + 1

        return str(ans) + "\n"
    except:
        return "0\n"
