        c2 = c5 = 0
        while num % 2 == 0:
            num //= 2
            c2 += 1
        while num % 5 == 0:
            num //= 5
            c5 += 1
        return c2, c5

    # dp[i][j] = list of (k2, k5) Pareto-optimal pairs
    dp = [[list() for _ in range(n)] for _ in range(n)]

    start_2, start_5 = count_factors(matrix[0][0])
    dp[0][0].append((start_2, start_5))

    # For path reconstruction - store just enough info
    # parent[i][j] stores path segments found

    for i in range(n):
        for j in range(n):
            if i == 0 and j == 0:
                continue

            c2, c5 = count_factors(matrix[i][j])

            candidates = []

            if i > 0 and dp[i-1][j]:
                for prev_k2, prev_k5 in dp[i-1][j]:
                    candidates.append((prev_k2 + c2, prev_k5 + c5))

            if j > 0 and dp[i][j-1]:
                for prev_k2, prev_k5 in dp[i][j-1]:
                    candidates.append((prev_k2 + c2, prev_k5 + c5))

            if not candidates:
                dp[i][j] = []
                continue

            # Pareto pruning: for each k2, keep minimum k5
            best_for_k2 = {}
            for k2, k5 in candidates:
                if k2 not in best_for_k2 or k5 < best_for_k2[k2]:
                    best_for_k2[k2] = k5

            # Keep pairs as (k2, k5)
            pareto_pairs = [(k2, best_for_k2[k2]) for k2 in sorted(best_for_k2.keys())]
            dp[i][j] = pareto_pairs

    # Find minimum trailing zeros at bottom-right
    if not dp[n-1][n-1]:
        return "0\n"

